	.text
	.even
	.globl	_nucleus
	.globl	_start
	.globl	___reltab

########################################################################
# _start: compute base, apply relocs and call C nucleus() function
########################################################################

_start:	mov	pc,	r5
	sub	$012,	r5

	mov	r0,	___sector_buffer
	mov	r1,	___schedule
	mov	r5,	___relbase

	# relocate the nucleus using the ___reltab generated by lsi-ld
	mov	$___reltab,r0
	add	r5,	r0	# r5 = reltab
	mov	(r0)+,	r2	# r2 = reloc count
1:	mov	(r0)+,	r3	# tmp = *(reloc++)
	add	r5,	r3	# tmp += relbase
	add	r5,	(r3)	# *tmp += relbase
	sob	r2,	1b

	# finally run the nucleus
	jmp	_nucleus

	.data
	.even
	.globl	___relbase
	.globl	___sector_buffer
	.globl	___schedule
___relbase:
	.word	0
___sector_buffer:
	.word	0
___schedule:
	.word	0
